    diaChiB: { label: "Địa chỉ B", value: "75 Đinh Tiên Hoàng, Phường Hoàn Kiếm, Thành phố Hà Nội", syncDir: "both" },
    maSoThueB: { label: "Mã số thuế B", value: "0100686223", syncDir: "both" },
