/**
 * @file calcLogic.js
 * @desc Logic nghiệp vụ tính thuế và định dạng số cho Calc Widget.
 */
import { formatNum, parseNum, numToVN, capFirst } from '../../utils/numberHelper.js';
import { setPageField } from '../../utils/domHelper.js';

import { AppState } from '../../core/state.js';

export function calculateValues(type, value, taxRate) {
    if (value === '' || value === undefined || value === null) {
        return {
            beforeNum: 0,
            taxNum: 0,
            afterNum: 0,
            beforeStr: '',
            taxStr: '',
            afterStr: '',
            textStr: ''
        };
    }

    let b = 0, t = 0, a = 0;
    
    if (type === 'before') {
        b = parseNum(value);
        t = taxRate > 0 ? Math.round(b * taxRate) : 0;
        a = b + t;
    } else if (type === 'tax') {
        t = parseNum(value);
        b = taxRate > 0 ? Math.round(t / taxRate) : 0;
        a = b + t;
    } else if (type === 'after') {
        a = parseNum(value);
        b = taxRate > 0 ? Math.round(a / (1 + taxRate)) : a;
        t = a - b;
    }
    
    const text = a === 0 ? '' : capFirst(numToVN(a)) + ' đồng';
    
    return {
        beforeNum: b,
        taxNum: t,
        afterNum: a,
        beforeStr: b === 0 ? '' : formatNum(b),
        taxStr: t === 0 ? '' : formatNum(t),
        afterStr: a === 0 ? '' : formatNum(a),
        textStr: text
    };
}

export function syncToPage(data, calcMaps) {
    // Cập nhật giá trị vào bảng Fields UI (nếu đang ở chế độ mặc định)
    if (AppState.isDefaultMode && AppState.fieldsContainer) {
        const rows = AppState.fieldsContainer.querySelectorAll('.vnpt-field-row');
        rows.forEach(row => {
            const keyInput = row.querySelector('.f-key');
            const valInput = row.querySelector('.f-val');
            if (keyInput && valInput) {
                const pk = keyInput.value.split(',')[0].trim();
                if (pk === 'calcBefore') valInput.value = data.beforeStr;
                if (pk === 'calcTax') valInput.value = data.taxStr;
                if (pk === 'calcAfter') valInput.value = data.afterStr;
                if (pk === 'calcText') valInput.value = data.textStr;
            }
        });
    }

    const processMap = (mapInfo, value) => {
        if (!mapInfo) return;
        const targets = Array.isArray(mapInfo) ? mapInfo : (mapInfo.sync || []);
        targets.forEach(n => setPageField(n, value));
    };

    processMap(calcMaps.before, data.beforeStr);
    processMap(calcMaps.tax, data.taxStr);
    processMap(calcMaps.after, data.afterStr);
    processMap(calcMaps.text, data.textStr);
}

Tôi đã hiểu lý do! Trong `calcLogic.js`, bộ tính toán đang tìm kiếm các hàng có primary key là `calcBefore`, `calcTax`, v.v. để điền giá trị vào bảng UI:

```javascript
// src/features/calc/calcLogic.js (Line 52)
const pk = keyInput.value.split(',')[0].trim();
if (pk === 'calcBefore') valInput.value = data.beforeStr;
if (pk === 'calcTax') valInput.value = data.taxStr;
// ...
```

Nhưng trong `defaults.js` mà tôi vừa sửa, tôi đã đổi Primary Key thành `"donGiaCA, ..."` (nghĩa là không còn chữ `calcBefore` ở đầu nữa).

**Để giải quyết vấn đề này và đảm bảo UI hiện đầy đủ danh sách ID:**

Tôi sẽ đưa `calcBefore`, `calcTax`, `calcAfter`, `calcText` vào làm **Primary Key** (đứng đầu tiên trong chuỗi f-key), theo sau là danh sách các ID đồng bộ. Như vậy:
1.  Bộ tính toán vẫn tìm được hàng để cập nhật UI.
2.  Ô `f-key` sẽ hiện: `calcAfter, cuocDV, tongCong, ...` (đầy đủ các ID như bạn muốn).

Hãy để tôi sửa lại `src/core/defaults.js` lần cuối cho đúng ý đồ này.

