function doSync(type, val) {
    if (val === '') return; // Không sync khi giá trị rỗng (để tránh xóa form khi chưa nhập xong)
    buildFullDOMMap(); // Đảm bảo map mới nhất trước khi điền
    const res = calculateValues(type, val, TAX_RATE);

    // Lấy calcMaps mới nhất từ bảng Fields (f-key)
    const currentMaps = { before: [], tax: [], after: [], text: [] };
    if (AppState.fieldsContainer) {
        const rows = AppState.fieldsContainer.querySelectorAll('.vnpt-field-row');
        rows.forEach(row => {
            const fKey = row.querySelector('.f-key');
            if (fKey) {
                const keys = fKey.value.split(',').map(s => s.trim()).filter(Boolean);
                const pk = keys[0];
                if (pk === 'calcBefore') currentMaps.before = keys.slice(1);
                else if (pk === 'calcTax') currentMaps.tax = keys.slice(1);
                else if (pk === 'calcAfter') currentMaps.after = keys.slice(1);
                else if (pk === 'calcText') currentMaps.text = keys.slice(1);
            }
        });
    }

    // Nếu bảng trống (chưa nạp), fallback về một object rỗng
    syncToPage(res, currentMaps);
}

