    if (!AppState.panel.classList.contains('vnpt-pinned')) return;

    // Focus Guard: Nếu đang focus vào input/textarea thì không thu gọn
    const activeEl = document.activeElement;
    if (activeEl && AppState.panel.contains(activeEl)) return;

    // Hủy timeout mở nếu có
    if (pinTimeout) clearTimeout(pinTimeout);

    // Đợi 200ms mới thu lại
    pinTimeout = setTimeout(() => {
        AppState.panel.classList.add('vnpt-panel-collapsed');
    }, 200);
});

// Thêm listener cho toàn bộ input để tự động thu gọn khi blur (nếu chuột đã ra ngoài)
AppState.panel.addEventListener('focusout', (e) => {
    if (!AppState.panel.classList.contains('vnpt-pinned')) return;

    setTimeout(() => {
        const activeEl = document.activeElement;
        // Nếu focus mới không nằm trong panel và chuột không nằm trên panel
        if (!(activeEl && AppState.panel.contains(activeEl)) && !AppState.panel.matches(':hover')) {
            AppState.panel.classList.add('vnpt-panel-collapsed');
        }
    }, 100);
});

