function setupProvinceSync() {
    const provinceIds = ['tinhId', 'tinhIdNew', 'diaChiTruSoTinhIdNew'];
    provinceIds.forEach(pId => {
        const el = document.getElementById(pId);
        if (el && !el.dataset.widgetSyncBound) {
            el.dataset.widgetSyncBound = "1";
            const updateWidgetSkdt = () => {
                // Dùng setTimeout 50ms để đợi UI trang web ổn định sau khi chọn
                setTimeout(() => {
                    const province = getProvinceName();
                    if (province) {
                        const skdtVal = "SKDT " + province;
                        const lookup = getLabelLookup();
                        // Tìm key chuẩn chứa noiCapSoDkdn
                        let skdtKey = Array.from(lookup.values()).find(k => k.includes('noiCapSoDkdn'));
                        if (!skdtKey) skdtKey = Object.keys(DEFAULT_LABELS).find(k => k.includes('noiCapSoDkdn'));

                        if (skdtKey) {
                            addOrUpdateFieldRow(skdtKey, skdtVal, null, '', null, true);
                            saveFieldsToLocal();

                            // ĐIỀN NGƯỢC XUỐNG WEB NGAY LẬP TỨC (Dùng setPageField chuẩn)
                            import('../utils/domHelper.js').then(({ setPageField }) => {
                                const ids = skdtKey.split(',').map(s => s.trim());
                                ids.forEach(id => setPageField(id, skdtVal));
                            });
                        }
                    }
                }, 50);
            };

            // Lắng nghe cả input và change
            el.addEventListener('change', updateWidgetSkdt);
            el.addEventListener('input', updateWidgetSkdt);

            // Với Select2 (VNPT) cần listener đặc thù qua jQuery nếu có
            if (typeof $ !== 'undefined') {
                $(el).on('select2:select change', updateWidgetSkdt);
