export function parseAddressComponents(address) {
    if (!address) return { province: '', district: '', ward: '', street: '' };

    const parts = address.split(',').map(p => p.trim()).filter(Boolean);
    const n = parts.length;

    let province = '', district = '', ward = '', street = '';

    if (n === 0) return { province, district, ward, street };

    // Quy tắc thông minh: Nhận diện từ cuối lên đầu
    let provinceIdx = -1, districtIdx = -1;

    for (let i = n - 1; i >= 0; i--) {
        const p = parts[i].toLowerCase();
        // Nhận diện Tỉnh
        if (provinceIdx === -1 && (p.includes('tỉnh') || p.includes('thành phố') || p.includes('tp.'))) {
            provinceIdx = i;
            province = parts[i];
            continue;
        }
        // Nhận diện Quận/Huyện/Thị xã (nếu đứng trước Tỉnh hoặc là phần tử gần cuối)
        if (districtIdx === -1 && (p.includes('quận') || p.includes('huyện') || p.includes('thị xã') || p.includes('q.') || p.includes('h.'))) {
            districtIdx = i;
            district = parts[i];
            continue;
        }
    }

    // Fallback nếu không có từ khóa (Dùng vị trí)
    if (provinceIdx === -1) { provinceIdx = n - 1; province = parts[n - 1]; }
    if (districtIdx === -1 && n >= 2) { districtIdx = n - 2; district = parts[n - 2]; }

    // Phần Đường + Xã: Lấy tất cả những gì đứng trước Quận/Huyện (hoặc Tỉnh nếu không thấy Huyện)
    const cutIdx = districtIdx !== -1 ? districtIdx : provinceIdx;
    if (cutIdx > 0) {
        street = parts.slice(0, cutIdx).join(', ');
    } else {
        street = address;
    }

    // Gán Ward bằng District nếu không bóc tách sâu hơn
    ward = district;

    return {
        province: cleanProvinceName(province),
        district: cleanProvinceName(district),
        ward: cleanProvinceName(ward),
        street
    };
}

