export function parseAddressComponents(address) {
    if (!address) return { province: '', district: '', ward: '', street: '' };

    const parts = address.split(',').map(p => p.trim()).filter(Boolean);
    const n = parts.length;

    let province = '', district = '', ward = '', street = '';

    if (n === 0) return { province, district, ward, street };

    // Tỉnh: phần cuối cùng
    province = parts[n - 1] || '';

    // Quận/Huyện/Xã/Phường: phần thứ 2 từ phải sang
    if (n >= 2) {
        district = parts[n - 2];
        ward = parts[n - 2];
    }

    // Phần Đường (Street): Lấy tất cả những gì đứng TRƯỚC dấu phẩy thứ 2 từ phải sang
    // Ví dụ: "Số nhà 116, đường Võ Nguyên Giáp, Phường Cam Đường, Lào Cai"
    // => n = 4. Cắt lấy parts[0] và parts[1].
    if (n >= 3) {
        street = parts.slice(0, n - 2).join(', ');
    } else if (n === 2) {
        // Nếu chỉ có 2 phần (VD: Đường X, Tỉnh Y), lấy phần đầu
        street = parts[0];
    } else {
        street = address;
    }

    return {
        province: cleanProvinceName(province),
        district: cleanProvinceName(district),
        ward: cleanProvinceName(ward),
        street
    };
}

